mapper.update:
update nad_document set current_version_id = #{currentVersionId}, status = #{status},
    update_by = #{updateBy}, update_time = now()
where id = #{id}

update nad_document set status = #{status}, reviewer_user_id = #{reviewerUserId},
    rejection_reason = #{rejectionReason}, update_by = #{updateBy}, update_time = now()
where id = #{id}
